            "title": "ขั้นตอนการนำ  Proxy เข้าใน Maxcare แบบ Import",
            "content": "ขั้นตอนการนำ  Proxy เข้าใน Maxcare แบบ Import\n\n1.เลือกบัญชีที่ต้องการ ==&gt; คลิกขวา ==&gt; Enter Proxies\n\n2.นำ proxy มาวางในช่อง List Proxys ==&gt; เลือก Type ของ Proxy ในช่อง Proxy Type ==&gt; เลือกจำนวน บัญชี ต่อ Proxy หากกำหนด 2 หมายถึง ใช้ 2 บัญชี ต่อ 1 proxy ในช่อง Accounts/Proxy ==&gt;  ในช่อง Option import Proxy ตัวเลือกการนำเข้า เลือกระหว่าง Sequence(แบบเจาะจง) Random(แบบสุ่ม) ==&gt; หากต้องการให้ข้ามบัญชีที่มี Proxy อยู่เเล้วให้เลือกในช่อง Skip account that already have Proxy ==&gt; จากนั้นกด Confirm\n\n3.หลังจากที่นำเข้า Proxy เสร็จแล้ว ไปที่หน้า General configs   ==&gt; ไปที่เมนู Chang IP  เลือก Proxy ==&gt; ในช่อง Option เลือก Entered For each account เป็นการใช้ proxy ที่อยู่ในบัญชี ==&gt; จากนั้นกด Save ==&gt;เสร็จขั้นตอนการนำเข้า  Proxy แบบ Import",
