            "content": "โปรแกรมทำงานมาถึงหน้า 2fa แล้วปิดไป !\n\n1.โปรแกรมขึ้นว่า 2fa is in correct!\n\n2.โปรแกรมขึ้นว่า login fail!\n\n3.โปรแกรมขึ้นว่า close chrome\n\n4.โปรแกรมขึ้นว่า Error opening browser\n\nวิธีแก้ไข\n\n1.อัพเดตเวอร์ชัน Maxcare\n\nไปที่โฟล์เดอร์ Maxcare =&gt; AutoUpdate รอจนกว่าจะเสร็จ\n\nเสร็จสิ้นขั้นตอนการอัพเดตเวอร์ชัน Maxcare เข้าใช้งานเวอร์ชันล่าสุด\n\n2.อัพเดตโครมไดร์เวอร์\n\nไปที่ General configs =&gt; Update Chromedriver รอจนกว่าจะเสร็จ\n\nเสร็จสิ้นขั้นตอนการอัพเดตโครมไดร์เวอร์",
