            "title": "การนำเข้าในแต่ละบัญชี",
            "content": "การนำเข้าในแต่ละบัญชี\n\nเลือกบัญชีที่ต้องการนำเข้า Proxy\n\nคลิกขวา =&gt; Update data =&gt; Proxy\n\nนำ Ip Proxy มาวางในช่องว่าง\n\nเลือก Proxy type\n\nกำหนดจำนวนบัญชีต่อ IP Proxy\n\nจากนั้นกด Confirm",
            "type": "markdown",
            "images": [
              "image209.png",
              "image329.png",
              "image94.png",
              "image324.png"
            ]
